<https://example.org/openevidence/questions/q_peptic_ulcer_disease_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is omeprazole compared with other agents for Peptic Ulcer Disease?"^^xsd:string ;
    oe:answerText "A peptic ulcer is a lesion (sore) on the stomach lining, or duodenum. Peptic ulcers are probably a twentieth-century condition."^^xsd:string ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_peptic_ulcer_disease_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_peptic_ulcer_disease_efficacy-bou> ;
