    holon:evidenceLevel "Level-5" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/38755116> ;
    holon:inHolon <https://example.org/openevidence/questions/q_peptic_ulcer_disease_efficacy> ;
